import{_ as t,c as a,o,ag as r}from"./chunks/framework.Ci10AEOF.js";const u=JSON.parse('{"title":"Troubleshooting","description":"Symptoms and causes for a server that will not start, an Administrator that will not connect, channels that will not run, and the errors you are most likely to see","frontmatter":{"title":"Troubleshooting","description":"Symptoms and causes for a server that will not start, an Administrator that will not connect, channels that will not run, and the errors you are most likely to see"},"headers":[],"relativePath":"engine/troubleshooting.md","filePath":"engine/troubleshooting.md","lastUpdated":1793057853000}'),n={name:"engine/troubleshooting.md"};function s(i,e,d,h,l,c){return o(),a("div",null,e[0]||(e[0]=[r(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="server-will-not-start" tabindex="-1">Server will not start <a class="header-anchor" href="#server-will-not-start" aria-label="Permalink to &quot;Server will not start&quot;">​</a></h2><h3 id="java-not-found" tabindex="-1">Java not found <a class="header-anchor" href="#java-not-found" aria-label="Permalink to &quot;Java not found&quot;">​</a></h3><p><strong>Symptom:</strong> an error about a missing Java runtime or an unsupported version.</p><p>Confirm the version with <code>java -version</code>; OIE 4.7.0 requires Java 17 or later.</p><p>If more than one runtime is installed, name the one to use with a line <code>-jvm=&lt;path to the Java home directory&gt;</code> in <code>conf/custom.vmoptions</code>, or with the environment variable <code>INSTALL4J_JAVA_HOME_OVERRIDE</code> set to the Java home directory. Without either, the launcher searches for one, and <code>JAVA_HOME</code> is ignored whenever a <code>java</code> of version 17 or newer is on the <code>PATH</code>. See <a href="./server_process_management.html#choosing-a-java">Choosing a Java</a> for the search order.</p><p>In an install or archive, the <code>OIE_JAVA_PATH</code> environment variable is ignored, and a <code>-java-cmd</code> line in <code>conf/custom.vmoptions</code> stops the server from starting with <code>Unrecognized option: -java-cmd</code>. Remove the line.</p><p>SDKMAN users can run <code>sdk env install</code> in the source tree to pick up the version the project declares.</p><h3 id="port-already-in-use" tabindex="-1">Port already in use <a class="header-anchor" href="#port-already-in-use" aria-label="Permalink to &quot;Port already in use&quot;">​</a></h3><p><strong>Symptom:</strong> <code>http.port port is already in use: 8080</code> or <code>https.port port is already in use: 8443</code> in the log on startup. The server does not serve, and in the archive install its process keeps running.</p><p>Find the process holding the port (<code>lsof -i :8443</code> on Linux and macOS, <code>netstat -ano | findstr 8443</code> on Windows), then stop it or move OIE. The ports live in <code>conf/mirth.properties</code>:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">http.port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 8080</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">https.port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 8443</span></span></code></pre></div><h3 id="database-connection-failed" tabindex="-1">Database connection failed <a class="header-anchor" href="#database-connection-failed" aria-label="Permalink to &quot;Database connection failed&quot;">​</a></h3><p><strong>Symptom:</strong> <code>Error establishing connection to database, retrying startup in &lt;n&gt; milliseconds</code>, followed by <code>Error establishing connection to database, aborting startup.</code> once the retries run out.</p><p>Check that the database is running and reachable through any firewall between it and OIE, then confirm <code>database</code>, <code>database.url</code>, <code>database.username</code>, and <code>database.password</code> in <code>mirth.properties</code>. The account needs rights to create and alter tables on first start, not just to read and write. <code>database.connection.maxretry</code> and <code>database.connection.retrywaitinmilliseconds</code> control how hard the server tries before giving up.</p><h3 id="out-of-memory" tabindex="-1">Out of memory <a class="header-anchor" href="#out-of-memory" aria-label="Permalink to &quot;Out of memory&quot;">​</a></h3><p><strong>Symptom:</strong> <code>OutOfMemoryError</code> in the log.</p><p>Raise the heap in <code>conf/custom.vmoptions</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-Xmx1024m</span></span></code></pre></div><p>If that only delays the failure, the cause is usually retained state rather than heap size: a global or global channel map that grows per message and is never cleared, or a channel loading an unbounded result set. The global map holds its memory until the server restarts, or until a <strong>Redeploy All</strong> clears it when the server setting <strong>Clear global map on redeploy</strong> asks for it. A global channel map is cleared when its channel is undeployed and deployed again, if the channel&#39;s <strong>Clear global channel map on deploy</strong> setting is on.</p><h2 id="administrator-cannot-connect" tabindex="-1">Administrator cannot connect <a class="header-anchor" href="#administrator-cannot-connect" aria-label="Permalink to &quot;Administrator cannot connect&quot;">​</a></h2><h3 id="connection-refused" tabindex="-1">Connection refused <a class="header-anchor" href="#connection-refused" aria-label="Permalink to &quot;Connection refused&quot;">​</a></h3><p>Verify the server is running and that port 8443 is reachable. Check <code>https.host</code> in <code>mirth.properties</code>: set to <code>127.0.0.1</code> it accepts local connections only, which looks identical to a firewall problem from another machine.</p><h3 id="certificate-errors" tabindex="-1">Certificate errors <a class="header-anchor" href="#certificate-errors" aria-label="Permalink to &quot;Certificate errors&quot;">​</a></h3><p>The certificate generated on first start is signed by the engine&#39;s own generated certificate authority, which clients do not trust, so browsers and the desktop Administrator will warn. For production, install a CA-signed certificate into the keystore. If the handshake fails outright rather than warning, compare <code>https.server.protocols</code> and <code>https.ciphersuites</code> against what the client offers.</p><h3 id="login-fails" tabindex="-1">Login fails <a class="header-anchor" href="#login-fails" aria-label="Permalink to &quot;Login fails&quot;">​</a></h3><p>On a new database the <code>admin</code> password is generated at first start, not <code>admin</code>; see <a href="./accessing_the_administrator.html#initial-admin-password">Initial admin password</a>. Otherwise confirm the credentials, then check whether the account is locked after exceeding <code>password.retrylimit</code>, or whether the password has expired under <code>password.expiration</code>. See <a href="./user_management.html#password-policy">Password policy</a> for both. Reset from the CLI with <code>user changepw admin &quot;a-new-password-here&quot;</code>; the new password must meet the same policy.</p><h2 id="channel-issues" tabindex="-1">Channel issues <a class="header-anchor" href="#channel-issues" aria-label="Permalink to &quot;Channel issues&quot;">​</a></h2><h3 id="channel-will-not-start" tabindex="-1">Channel will not start <a class="header-anchor" href="#channel-will-not-start" aria-label="Permalink to &quot;Channel will not start&quot;">​</a></h3><p>Check the Server Log tab on the Dashboard first; a channel that refuses to start almost always logged why. The usual causes are a source connector port already in use, a channel dependency that failed to start in the same start request, an exception thrown from a deploy script, or, for a Database Reader or a File Reader over SFTP or FTP, an unreachable external resource.</p><h3 id="messages-not-being-received" tabindex="-1">Messages not being received <a class="header-anchor" href="#messages-not-being-received" aria-label="Permalink to &quot;Messages not being received&quot;">​</a></h3><p>Confirm the sending system is pointing at the right host and port and that nothing between them is blocking it. For TCP and MLLP, a mismatched transmission mode presents as a connection that opens and then goes quiet. For File Reader, check the directory and the filename filter. For Database Reader, run the query by hand against the same account. The Connection Log tab on the Dashboard shows connection events as they happen.</p><h3 id="messages-stuck-in-queue" tabindex="-1">Messages stuck in queue <a class="header-anchor" href="#messages-stuck-in-queue" aria-label="Permalink to &quot;Messages stuck in queue&quot;">​</a></h3><p>Open the destination&#39;s failures in the Message Browser and read the error rather than the count. Common causes are an unreachable destination, an authentication failure that retries forever, and a retry interval long enough that the queue looks stalled when it is only slow. Queue settings are per destination.</p><h3 id="transformer-errors" tabindex="-1">Transformer errors <a class="header-anchor" href="#transformer-errors" aria-label="Permalink to &quot;Transformer errors&quot;">​</a></h3><p>Open the message in the Message Browser and read the Errors tab. <code>TypeError</code> usually means a method was called on the empty value that a field path not in this message returns (reading the missing path alone raises no error), <code>ReferenceError</code> an undefined variable, most often <code>tmp</code> in a transformer with no outbound template configured. Load a real sample message in the transformer editor and check the path against the actual structure rather than the specification.</p><p>To capture what a script saw for a specific message, put it in the channel map rather than the log. It then appears on that message&#39;s Mappings tab in the Message Browser, attached to the message it describes:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;debugMessageType&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, msg[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;MSH&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;MSH.9&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;MSH.9.1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><h3 id="filter-not-working" tabindex="-1">Filter not working <a class="header-anchor" href="#filter-not-working" aria-label="Permalink to &quot;Filter not working&quot;">​</a></h3><p>Check rule order and the AND/OR operators between rules, and confirm field paths against a real message. In a JavaScript filter, <code>return true</code> accepts the message and <code>return false</code> rejects it. A filter shares its scope with the transformer on the same connector, so a value the filter writes to <code>msg</code>, or to <code>tmp</code> where an outbound template exists, is still there when the transformer runs.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><h3 id="high-cpu" tabindex="-1">High CPU <a class="header-anchor" href="#high-cpu" aria-label="Permalink to &quot;High CPU&quot;">​</a></h3><p>Look for high-volume channels with expensive transformers, polling sources set to poll far more often than the data arrives, and loops in scripts over repeating segments that rescan the message each iteration. Raising processing threads helps only where message order does not matter.</p><h3 id="high-memory" tabindex="-1">High memory <a class="header-anchor" href="#high-memory" aria-label="Permalink to &quot;High memory&quot;">​</a></h3><p>Check for large messages that would be better handled as attachments. Review global and global channel map usage: anything put in the global map stays until the server restarts, something removes it, or a <strong>Redeploy All</strong> clears it when the server setting <strong>Clear global map on redeploy</strong> asks for it. A global channel map is cleared when its channel is undeployed and deployed again, if the channel&#39;s <strong>Clear global channel map on deploy</strong> setting is on.</p><h3 id="slow-database" tabindex="-1">Slow database <a class="header-anchor" href="#slow-database" aria-label="Permalink to &quot;Slow database&quot;">​</a></h3><p>Where a read replica exists, point the read-only connection pool at it with the <code>database-readonly.*</code> properties (see <a href="./database_support.html">Database Support</a>), keep statistics and indexes current, and raise <code>database.max-connections</code> if the pool is saturated. Configure pruning before tuning anything else.</p><h2 id="common-error-messages" tabindex="-1">Common error messages <a class="header-anchor" href="#common-error-messages" aria-label="Permalink to &quot;Common error messages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Where to look</th></tr></thead><tbody><tr><td><code>Address already in use</code></td><td>Port conflict</td><td>Change the port or stop the conflicting process</td></tr><tr><td><code>Error establishing connection to database</code></td><td>Database unreachable or credentials wrong</td><td><code>database.*</code> settings and network path</td></tr><tr><td><code>OutOfMemoryError</code></td><td>Heap exhausted, or retained state</td><td><code>-Xmx</code>, then map growth</td></tr><tr><td><code>SSLHandshakeException</code></td><td>No protocol or cipher in common</td><td><code>https.server.protocols</code> for connections to the engine, <code>https.client.protocols</code> for connections a connector makes, and <code>https.ciphersuites</code></td></tr><tr><td><code>ConnectException: Connection refused</code></td><td>Destination unreachable</td><td>Host, port, firewall</td></tr><tr><td><code>SocketTimeoutException</code></td><td>Network or downstream timeout</td><td>Connector timeout settings</td></tr><tr><td><code>ScriptCompileException</code></td><td>JavaScript syntax error in a deploy or undeploy script</td><td>The deploy and undeploy scripts of the channel id named in the message</td></tr><tr><td><code>MirthJavascriptTransformerException</code></td><td>Runtime error in a filter or transformer script</td><td>Errors tab in the Message Browser</td></tr></tbody></table><h2 id="getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting help&quot;">​</a></h2><ul><li><strong>Logs:</strong> <code>logs/mirth.log</code> on the server</li><li><strong>Events:</strong> system events for operational issues</li><li><strong>Discord:</strong> <a href="https://discord.gg/azdehW2Zrx" target="_blank" rel="noreferrer">join the community</a></li><li><strong>GitHub Issues:</strong> <a href="https://github.com/OpenIntegrationEngine/engine/issues" target="_blank" rel="noreferrer">report a bug</a></li><li><strong>Security issues:</strong> the Eclipse Foundation Security Team, <a href="mailto:security@eclipse-foundation.org" target="_blank" rel="noreferrer">security@eclipse-foundation.org</a> (<a href="https://www.eclipse.org/security/" target="_blank" rel="noreferrer">process</a>)</li></ul>`,51)]))}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
